using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Linq;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
namespace ScreenText {
 public partial class MainForm {
  readonly AiProviderInfo copilotProvider=new AiProviderInfo("copilot","GitHub Copilot","Uses your Copilot plan","Connect using the official Copilot CLI login.");
  CopilotConnection copilot;CopilotPreferences copilotPreferences;ThemeCombo copilotHostChoice,copilotTranslationModel,copilotExtractionModel;TextBox copilotEnterprise;Label copilotIdentity,copilotFeedback,copilotModels;Button copilotConnect,copilotCheck,copilotSignOut,copilotCancel,copilotUse,openAiUse,copilotModelRefresh;CancellationTokenSource copilotOperation;bool copilotWorking,copilotExitPending,updatingCopilot;
  bool UsingCopilot{get{return activeAiProvider.Id=="copilot";}}
  bool CopilotSignedIn{get{return copilot!=null&&copilot.Account!=null&&copilot.Account.authenticated&&copilot.Account.host==copilotPreferences.Host;}}
  string CopilotSelectedHost(){return CopilotHost.Normalize(copilotHostChoice.SelectedIndex==0?"github.com":copilotEnterprise.Text);}
  void SaveCopilotPreferences(){if(!preview&&!isolateAiCatalog)try{copilotPreferences.Save();}catch{copilotFeedback.Text="The selection changed but could not be saved.";}}
  void UseAiProvider(bool github){if(busy||aiWorking||copilotWorking)return;activeCopilot=github;if(!preview&&!isolateAiCatalog)try{File.WriteAllText(Path.Combine(AppStorage.SettingsDirectory,"ai-active-provider.txt"),activeAiProvider.Id);}catch{status.Text="Provider selected but could not be saved.";}UpdateAiControls();if(github&&!isolateAiCatalog)CheckCopilotOnStartup();}
  async void CheckCopilotOnStartup(){if(isolateAiCatalog||closing||copilotWorking||busy||aiWorking)return;await RunCopilotAction("status");}
  void CreateCopilotSettings(bool isolated){
   copilot=new CopilotConnection();copilotPreferences=isolated?new CopilotPreferences():CopilotPreferences.Load();
   var account=AiStack();copilotUse=Button("Use for AI",(s,e)=>UseAiProvider(true),true);copilotUse.Width=200;account.Controls.Add(copilotUse);
   copilotHostChoice=new ThemeCombo{Width=380,Font=new Font("Segoe UI",10),AccessibleName="Copilot GitHub environment"};copilotHostChoice.Items.AddRange(new object[]{"GitHub.com","Enterprise Cloud (*.ghe.com)"});account.Controls.Add(copilotHostChoice);
   var server=new RoundedPanel{Width=380,Height=36,Padding=new Padding(10,8,10,6),Margin=new Padding(0,7,0,0)};copilotEnterprise=new TextBox{Dock=DockStyle.Fill,BorderStyle=BorderStyle.None,Font=new Font("Segoe UI",10),AccessibleName="Enterprise Cloud hostname",MaxLength=80};server.Controls.Add(copilotEnterprise);account.Controls.Add(server);
   copilotIdentity=AiLabel("Not checked yet");copilotIdentity.Font=new Font("Segoe UI",11,FontStyle.Bold);copilotIdentity.MaximumSize=new Size(420,0);account.Controls.Add(copilotIdentity);
   var actions=new FlowLayoutPanel{Width=420,MaximumSize=new Size(420,0),AutoSize=true,WrapContents=true,Margin=new Padding(0,8,0,0)};
   copilotConnect=Button("Sign in via CLI",async(s,e)=>await RunCopilotAction("login"));copilotCheck=Button("Check connection",async(s,e)=>await RunCopilotAction("status"));copilotSignOut=Button("Sign out of Copilot CLI",async(s,e)=>{if(!CopilotSignedIn)return;string identity=copilot.Account.login+" · "+copilot.Account.host;if(Confirm("Sign out of Copilot CLI?","Sign out "+identity+"?\n\nThis removes this account's shared Copilot CLI sign-in on this Windows account, including use by other tools relying on it. GitHub browser and VS Code sessions are not explicitly signed out. Your ChatGPT connection is unchanged."))await RunCopilotAction("logout");});copilotCancel=Button("Cancel",(s,e)=>{if(copilotOperation!=null)copilotOperation.Cancel();});copilotConnect.Width=110;copilotCheck.Width=126;copilotSignOut.Width=168;copilotConnect.Margin=copilotCheck.Margin=new Padding(0,0,8,0);copilotSignOut.Margin=Padding.Empty;copilotCancel.Width=90;actions.Controls.AddRange(new Control[]{copilotConnect,copilotCheck,copilotSignOut,copilotCancel});account.Controls.Add(actions);
   copilotFeedback=AiLabel("Check the CLI account or sign in using your browser.");copilotFeedback.MaximumSize=new Size(420,0);account.Controls.Add(copilotFeedback);
   var privacy=AiLabel("Shared CLI login. Closing ScreenText keeps you signed in. Sign out also affects other tools using this CLI account.");privacy.MaximumSize=new Size(420,0);account.Controls.Add(privacy);
   var models=AiStack();models.Controls.Add(AiLabel("Translation model"));copilotTranslationModel=new ThemeCombo{Width=380,Font=new Font("Segoe UI",10),AccessibleName="Copilot translation model"};models.Controls.Add(copilotTranslationModel);models.Controls.Add(AiLabel("Image extraction model"));copilotExtractionModel=new ThemeCombo{Width=380,Font=new Font("Segoe UI",10),AccessibleName="Copilot extraction model"};models.Controls.Add(copilotExtractionModel);copilotModels=AiLabel("");copilotModels.MaximumSize=new Size(420,0);models.Controls.Add(copilotModels);copilotModelRefresh=Button("Refresh models",async(s,e)=>await RunCopilotAction("status"));copilotModelRefresh.Width=160;models.Controls.Add(copilotModelRefresh);
   RegisterAiProviderSettings(copilotProvider,SettingsSection("GitHub Copilot account","Official CLI login · No API key.",account),SettingsSection("Copilot models","Separate defaults. Available models depend on your plan and company policy.",models));
   copilotHostChoice.SelectedIndex=copilotPreferences.Host=="github.com"?0:1;copilotEnterprise.Text=copilotPreferences.Host=="github.com"?"":copilotPreferences.Host;server.Visible=copilotHostChoice.SelectedIndex==1;
   Action hostChanged=()=>{server.Visible=copilotHostChoice.SelectedIndex==1;try{string host=CopilotSelectedHost();if(host!=copilotPreferences.Host){copilotPreferences.Host=host;copilot.Forget();SaveCopilotPreferences();}}catch(ArgumentException){}UpdateAiControls();};copilotHostChoice.SelectedIndexChanged+=(s,e)=>hostChanged();copilotEnterprise.TextChanged+=(s,e)=>hostChanged();
   copilotTranslationModel.SelectedIndexChanged+=(s,e)=>SaveCopilotModel(copilotTranslationModel,false);copilotExtractionModel.SelectedIndexChanged+=(s,e)=>SaveCopilotModel(copilotExtractionModel,true);
  }
  bool Confirm(string title,string message){return MessageBox.Show(settingsWindow!=null&&settingsWindow.Visible?settingsWindow:this,message,title,MessageBoxButtons.YesNo,MessageBoxIcon.Question,MessageBoxDefaultButton.Button2)==DialogResult.Yes;}
  void SaveCopilotModel(ThemeCombo combo,bool extraction){if(updatingCopilot||updatingAi||busy)return;var model=SelectedAi(combo) as CopilotModel;if(model==null)return;if(extraction)copilotPreferences.ExtractionModel=model.id;else copilotPreferences.TranslationModel=model.id;SaveCopilotPreferences();UpdateAiControls();}
  List<CopilotModel> CopilotChoices(){var models=CopilotSignedIn?new List<CopilotModel>(copilot.Account.models):new List<CopilotModel>();foreach(string id in new[]{copilotPreferences.TranslationModel,copilotPreferences.ExtractionModel})if(!models.Any(m=>m.id==id))models.Add(new CopilotModel{id=id,name="\u26A0 "+id+" · Unverified"});return models;}
  void FillCopilotModel(ThemeCombo combo,bool extraction,bool enabled){var chosen=extraction?copilotPreferences.ExtractionModel:copilotPreferences.TranslationModel;combo.SelectedIndex=-1;combo.Items.Clear();foreach(var model in CopilotChoices())combo.Items.Add(model);for(int i=0;i<combo.Items.Count;i++)if(((CopilotModel)combo.Items[i]).id==chosen)combo.SelectedIndex=i;combo.Enabled=enabled;combo.AccessibleDescription="Copilot "+(extraction?"extraction":"translation")+" model: "+chosen;workspaceHints.SetToolTip(combo,combo.AccessibleDescription);}
  void UpdateCopilotControls(){if(copilotHostChoice==null)return;updatingCopilot=true;try{bool enabled=!busy&&!aiWorking&&!copilotWorking;copilotHostChoice.Enabled=copilotEnterprise.Enabled=enabled;copilotConnect.Enabled=copilotCheck.Enabled=copilotModelRefresh.Enabled=enabled;copilotSignOut.Enabled=enabled&&CopilotSignedIn;copilotCancel.Visible=copilotWorking;copilotUse.Enabled=enabled&&!UsingCopilot;copilotUse.Text=UsingCopilot?"Active AI provider":"Use for AI";if(openAiUse!=null){openAiUse.Enabled=enabled&&UsingCopilot;openAiUse.Text=UsingCopilot?"Use for AI":"Active AI provider";}
   copilotIdentity.Text=CopilotSignedIn?"Signed in · "+copilot.Account.login+"\n"+copilot.Account.host+" · Copilot CLI":copilot.Account==null?"Connection not checked":"Not signed in for this environment";
   FillCopilotModel(copilotTranslationModel,false,enabled);FillCopilotModel(copilotExtractionModel,true,enabled);if(UsingCopilot){FillCopilotModel(workspaceTranslationModel,false,enabled&&AiSignedIn);FillCopilotModel(workspaceExtractionModel,true,enabled&&AiSignedIn);}
   copilotModels.Text=!CopilotSignedIn?"Check connection to load this account's catalog.":copilot.Account.catalogLoaded&&copilot.Account.accessIssue==""?"Account catalog loaded. Auto lets Copilot choose a model. Image support varies by model; your saved choices are kept.":copilot.Account.accessIssue;
  }finally{updatingCopilot=false;}}
  async Task RunCopilotAction(string action){
   if(busy||aiWorking||copilotWorking)return;string host;try{host=CopilotSelectedHost();}catch(ArgumentException ex){copilotFeedback.Text=ex.Message;return;}
   copilotWorking=true;copilotOperation=new CancellationTokenSource();copilotFeedback.Text=action=="login"?"Complete the official Copilot CLI sign-in in your browser…":action=="logout"?"Removing this account's shared CLI sign-in…":"Checking the Copilot CLI account and models. No AI request is sent.";UpdateAiControls();
   try{if(action=="logout"){await copilot.SignOut(host,copilot.Account.login,copilotOperation.Token);copilotFeedback.Text="Signed out of this Copilot CLI account locally. Other tools using its shared CLI sign-in are affected. GitHub authorization was not revoked.";}else{var account=await copilot.Check(host,action=="login",copilotOperation.Token);copilotFeedback.Text=account.authenticated?(account.accessChecked?"Connected. Account and model catalog checked; no AI request was sent.":account.accessIssue):account.accessIssue;}}
   catch(OperationCanceledException){if(!closing)copilotFeedback.Text="Canceled. Check connection to see whether the CLI sign-in changed.";}
   catch(Exception ex){if(!closing)copilotFeedback.Text=ex is AiConnectionException?ex.Message:"Copilot could not finish this action.";}
   finally{copilotWorking=false;copilotOperation.Dispose();copilotOperation=null;if(!closing){UpdateAiControls();if(copilotExitPending)BeginInvoke((Action)ExitApplication);}}
  }
 }
}
